// Practical Android/Kotlin interview bank. These are recurring interview themes, not a promise that every company asks every question.
const INTERVIEW_QUESTION_BANK = [
// Kotlin & concurrency
{id:'K01',category:'Kotlin & concurrency',level:'Core',prompt:'Explain structured concurrency. What does a parent Job guarantee, and what does it not guarantee?',answer:['Child coroutines belong to a scope and are cancelled with their parent.','A regular parent generally fails when a child fails; SupervisorJob/supervisorScope changes sibling failure propagation.','Structured concurrency does not make blocking calls non-blocking or guarantee work survives process death.'],follow:'When would you use supervisorScope for independent dashboard requests?',signals:'Can reason about ownership, cancellation and failure propagation—not just repeat “coroutines are lightweight”.',traps:'Treating GlobalScope as a lifecycle strategy; assuming SupervisorJob catches every exception.',labs:['LAB 01']},
{id:'K02',category:'Kotlin & concurrency',level:'Core',prompt:'When would you choose launch, async, withContext and a Flow instead of another?',answer:['launch starts work with Job and no result value.','async returns Deferred<T> for concurrent result composition; await observes the result.','withContext changes context for a structured block and returns its value.','Flow models a stream over time; its collection and cancellation semantics matter.'],follow:'Why is async often unnecessary for a single sequential repository call?',signals:'Chooses by semantics and ownership, not syntax preference.',traps:'Using async for fire-and-forget work or GlobalScope.',labs:['LAB 01','LAB 02']},
{id:'K03',category:'Kotlin & concurrency',level:'Core',prompt:'What is the difference between Dispatchers.IO and Dispatchers.Default? Is IO an unlimited thread pool?',answer:['Default is intended for CPU-bound work; IO for blocking I/O.','IO shares implementation resources with Default and has configurable parallelism; it is not a promise of one thread per task.','Dispatchers do not make a blocking API cancellable by themselves.'],follow:'How would you handle a legacy blocking SDK that ignores interruption?',signals:'Understands scheduler intent and blocking limitations.',traps:'Saying IO is always faster or moves all work off Main automatically.',labs:['LAB 01']},
{id:'K04',category:'Kotlin & concurrency',level:'Intermediate',prompt:'How do cancellation and exceptions interact in coroutines? Why can catch(Exception) be dangerous?',answer:['CancellationException is part of cooperative cancellation and should normally be rethrown.','Cancellation is observed at suspension points or explicit checks.','Use finally for cleanup; use NonCancellable only for bounded suspending cleanup.','Exception handling belongs at a meaningful scope boundary.'],follow:'How do you test cancellation of a Flow pipeline?',signals:'Can design cleanup and cancellation tests.',traps:'Swallowing CancellationException; wrapping all work in NonCancellable.',labs:['LAB 01','LAB 02']},
{id:'K05',category:'Kotlin & concurrency',level:'Intermediate',prompt:'Compare StateFlow and SharedFlow. What delivery guarantees do they provide?',answer:['StateFlow always has a current value and conflates by equality; collectors see latest state.','SharedFlow configures replay, buffer and overflow; it can broadcast events to multiple collectors.','Neither is a durable event queue; process death loses in-memory emissions.'],follow:'How would you guarantee a critical event is not lost across process death?',signals:'Distinguishes state, ephemeral events and durable data.',traps:'Calling SharedFlow a guaranteed one-time event channel.',labs:['LAB 02','LAB 03','LAB 12']},
{id:'K06',category:'Kotlin & concurrency',level:'Advanced',prompt:'Explain StateFlow update atomicity and how you avoid lost updates with concurrent writers.',answer:['Use update { old -> new } for atomic read-modify-write.','Avoid mutating objects held inside state; publish immutable snapshots.','Confine mutable state or synchronize access where multiple writers exist.'],follow:'Why can two sequential value = value.copy(...) operations race?',signals:'Understands thread safety beyond using StateFlow.',traps:'Assuming StateFlow makes nested mutable objects thread-safe.',labs:['LAB 02','LAB 01']},
{id:'K07',category:'Kotlin & concurrency',level:'Advanced',prompt:'What are inline, reified, crossinline and noinline used for, and what trade-offs do inline functions create?',answer:['Inline substitutes function bodies at call sites and enables reified type parameters.','reified exposes type information for inline generic functions.','noinline retains a function object; crossinline prevents non-local returns.','Inlining can increase bytecode size and affect debugging/API design.'],follow:'Why can public inline functions create binary compatibility concerns?',signals:'Can explain language features with runtime and API consequences.',traps:'Assuming inline always improves performance.',labs:['LAB 37']},
{id:'K08',category:'Kotlin & concurrency',level:'Advanced',prompt:'How do equals/hashCode, data classes, sealed hierarchies and variance affect API design?',answer:['Equality must align with identity semantics and collection usage.','Data class generated methods use primary-constructor properties.','Sealed types constrain known variants and support exhaustive handling.','Variance (out/in) controls safe producer/consumer substitution.'],follow:'When is a data class a poor domain entity?',signals:'Understands modeling and API contracts.',traps:'Using data-class structural equality for mutable identity-bearing entities.',labs:['LAB 08','LAB 37']},
// Android platform
{id:'A01',category:'Android platform & lifecycle',level:'Core',prompt:'Walk through Activity lifecycle when opening another Activity, pressing Home, rotating, and returning.',answer:['Describe callbacks as observable transitions, not a single universal sequence.','Differentiate stopped vs destroyed and configuration recreation.','Tie UI collection to lifecycle; persist only state needed for recreation.','Do not assume callbacks are guaranteed before process kill.'],follow:'What state belongs in ViewModel, SavedStateHandle, Room or DataStore?',signals:'Explains lifecycle with concrete state ownership.',traps:'Saying onDestroy always runs or ViewModel survives process death.',labs:['LAB 03','LAB 05']},
{id:'A02',category:'Android platform & lifecycle',level:'Core',prompt:'What happens when Android kills your app process in the background? How should the app recover?',answer:['The process and in-memory objects disappear; persistent storage remains.','The system may later recreate an Activity with saved state, but callbacks are not a persistence mechanism.','Persist durable user data in database/files/preferences; use SavedStateHandle for small transient reconstruction state.'],follow:'How would you test process recreation rather than just rotation?',signals:'Separates configuration change from process death.',traps:'Persisting huge objects in Bundle; assuming ViewModel survives process death.',labs:['LAB 05','LAB 10']},
{id:'A03',category:'Android platform & lifecycle',level:'Intermediate',prompt:'What causes an ANR, and how would you investigate one from a production report?',answer:['Main thread is blocked or fails to respond within system thresholds for input/broadcast/service scenarios.','Inspect traces, main-thread stack, StrictMode, Perfetto and slow I/O/locks.','Reproduce under representative conditions and fix root cause, not merely move arbitrary code to IO.'],follow:'What if the main thread is waiting on a lock held by a background thread?',signals:'Uses traces and causal diagnosis.',traps:'Assuming every ANR is network on Main.',labs:['LAB 23','LAB 45']},
{id:'A04',category:'Android platform & lifecycle',level:'Intermediate',prompt:'Explain saved instance state vs persistent storage. What belongs in each?',answer:['Saved state restores small transient UI/navigation inputs after system recreation.','Room/files store durable app data; DataStore stores small preferences/settings.','Avoid storing large payloads or canonical business state in Bundles.'],follow:'How would you restore a multi-step checkout after process death?',signals:'Chooses storage by durability and size.',traps:'Treating saved state as a database.',labs:['LAB 05','LAB 10','LAB 12']},
{id:'A05',category:'Android platform & lifecycle',level:'Intermediate',prompt:'How do runtime permissions work when a user denies, permanently denies, or revokes permission in Settings?',answer:['Request contextually and handle denial as a normal state.','Check current permission when capability is used/resumed; do not cache permission forever.','Offer degraded functionality and explain why the feature needs access.'],follow:'How do approximate and precise location change product behavior?',signals:'Permission UX and OS state awareness.',traps:'Repeatedly prompting or treating permission as guaranteed.',labs:['LAB 14','LAB 29']},
{id:'A06',category:'Android platform & lifecycle',level:'Advanced',prompt:'When should you use WorkManager, a foreground service, or an immediate in-process coroutine?',answer:['Coroutine for work owned by a live process/scope and not required to outlive it.','WorkManager for deferrable, guaranteed/schedulable work with constraints and retry.','Foreground service for user-noticeable ongoing work that meets current platform policy and type requirements.'],follow:'Which one would you choose for a large user-requested upload?',signals:'Maps API to user-visible semantics and OS policy.',traps:'Using WorkManager for exact real-time timing; foreground service for everything.',labs:['LAB 15','LAB 16']},
{id:'A07',category:'Android platform & lifecycle',level:'Advanced',prompt:'What is Binder IPC, and why should you avoid putting large objects in Intents or saved-state Bundles?',answer:['Binder is Android’s IPC mechanism used by framework and app components.','Transactions serialize data and are constrained by shared process transaction buffer.','Pass identifiers and retrieve large data from storage/content providers instead of huge Bundles.'],follow:'How would you share a large file safely between apps?',signals:'Knows platform boundaries and data transport constraints.',traps:'Assuming Bundle size limit is an unlimited per-object budget.',labs:['LAB 43']},
{id:'A08',category:'Android platform & lifecycle',level:'Advanced',prompt:'Explain task/back stack behavior, launch modes and deep links. What security checks belong in a deep-link destination?',answer:['Task stack and launch flags influence Activity reuse/back behavior.','Verified App Links reduce ambiguity but do not replace authorization.','Validate URI structure, IDs, user ownership and state server-side.'],follow:'How do you prevent an exported Activity from becoming an authorization bypass?',signals:'Combines navigation and security.',traps:'Trusting a deep-link ID because it came from an official link.',labs:['LAB 06','LAB 27']},
// Compose
{id:'C01',category:'Jetpack Compose',level:'Core',prompt:'What triggers recomposition, and how is Compose state observed?',answer:['Composable reads of snapshot state are tracked in a snapshot observation scope.','A write can invalidate scopes that read the changed state.','Recomposition is an optimization mechanism; do not rely on it as a side-effect callback.'],follow:'Why can mutating a list in place fail to update the UI?',signals:'Understands observable state and immutable updates.',traps:'Thinking every recomposition redraws the entire screen.',labs:['LAB 04']},
{id:'C02',category:'Jetpack Compose',level:'Core',prompt:'What is the difference between remember, rememberSaveable and ViewModel?',answer:['remember caches across recompositions while the composable remains in composition.','rememberSaveable saves supported small state through saved-state mechanism.','ViewModel owns screen/business presentation state beyond a particular composition and survives configuration change, not process death by itself.'],follow:'Where would you store a selected tab vs a draft order?',signals:'Chooses state holder based on ownership and durability.',traps:'Using rememberSaveable for large/domain-critical data.',labs:['LAB 04','LAB 05']},
{id:'C03',category:'Jetpack Compose',level:'Intermediate',prompt:'Explain Composition, Layout and Drawing phases. How can deferring a state read improve performance?',answer:['Composition describes UI tree, Layout measures/places, Drawing renders.','Reading rapidly changing state later (layout/draw lambda) can skip earlier phases.','Measure with tracing/benchmarking; do not blindly optimize.'],follow:'When is Modifier.offset { } preferable to offset(y = ...)?',signals:'Connects Compose internals to measurable frame work.',traps:'Claiming lambda modifiers always improve performance.',labs:['LAB 04','LAB 20','LAB 46']},
{id:'C04',category:'Jetpack Compose',level:'Intermediate',prompt:'What makes a parameter stable or unstable, and what does @Stable/@Immutable promise?',answer:['Stability informs compiler/runtime skipping decisions.','Immutable types promise observable values do not mutate; Stable types promise changes are observable.','Annotations are contracts, not magic optimization switches; false promises cause stale UI.'],follow:'How would you inspect compiler stability reports?',signals:'Knows correctness precedes skip optimization.',traps:'Annotating every model @Immutable without enforcing immutability.',labs:['LAB 04','LAB 20']},
{id:'C05',category:'Jetpack Compose',level:'Intermediate',prompt:'How do LaunchedEffect, DisposableEffect, SideEffect and rememberCoroutineScope differ?',answer:['LaunchedEffect runs a coroutine tied to composition and restarts when keys change.','DisposableEffect manages setup/cleanup of external resources.','SideEffect publishes successful composition state to non-Compose code.','rememberCoroutineScope provides a composition-bound scope for event callbacks.'],follow:'Why is launching a network request directly in a Composable body incorrect?',signals:'Understands effect lifecycle and key semantics.',traps:'Using effects as arbitrary event buses.',labs:['LAB 04']},
{id:'C06',category:'Jetpack Compose',level:'Advanced',prompt:'How would you debug a LazyColumn that janks or loses item state?',answer:['Use stable unique keys and contentType where appropriate.','Inspect expensive item composition, image decoding, allocations and state reads.','Measure frame timing with Macrobenchmark/Perfetto; verify fixes.'],follow:'What problems arise when list items use index as a key and data is inserted at the top?',signals:'Combines UI identity with profiling.',traps:'Adding remember everywhere or guessing from code appearance.',labs:['LAB 20','LAB 21','LAB 23']},
// Architecture
{id:'AR01',category:'Architecture & design',level:'Core',prompt:'What problem do Repository, UseCase and ViewModel layers solve? When would you avoid adding a use case?',answer:['Repositories abstract data sources and expose domain-friendly contracts.','Use cases isolate reusable or meaningful business operations.','ViewModels expose UI state and coordinate UI actions.','Avoid ceremony when a layer adds no policy, reuse or testability.'],follow:'Where should validation that affects multiple screens live?',signals:'Can justify boundaries rather than applying a template blindly.',traps:'One class per function without a reason.',labs:['LAB 08','LAB 09']},
{id:'AR02',category:'Architecture & design',level:'Intermediate',prompt:'Compare MVVM and MVI. What does unidirectional data flow buy you?',answer:['Both are patterns, not strict library implementations.','UDF makes state transitions and event flow explicit: UI action → state holder → new state → UI.','MVI often models a single immutable state and reducer; MVVM can also use UDF.'],follow:'How do you model one-off navigation/snackbar effects without losing them?',signals:'Discusses state/event semantics and testability.',traps:'Treating MVI as a mandatory framework or every event as state.',labs:['LAB 09','LAB 04']},
{id:'AR03',category:'Architecture & design',level:'Intermediate',prompt:'How do you decide module boundaries in a growing Android application?',answer:['Align modules with cohesive features/capabilities and ownership boundaries.','Minimize dependency surface and cycles; distinguish API from implementation.','Consider build graph, test isolation, team ownership and change frequency.'],follow:'When does modularization make a project worse?',signals:'Understands organizational and build trade-offs.',traps:'One module per class or premature micro-modules.',labs:['LAB 26','LAB 50']},
{id:'AR04',category:'Architecture & design',level:'Intermediate',prompt:'How does dependency injection help, and what are the trade-offs of Hilt/Koin/manual DI?',answer:['DI separates object construction from use and clarifies dependency graph.','Compile-time vs runtime resolution, startup cost, test overrides and platform compatibility differ.','Manual DI can be simpler for small graphs; frameworks help at scale.'],follow:'How would you scope a database, repository and ViewModel?',signals:'Can compare options in context.',traps:'Using DI framework as service locator.',labs:['LAB 07','LAB 40']},
{id:'AR05',category:'Architecture & design',level:'Advanced',prompt:'How would you design a feature API module so teams can implement features independently?',answer:['Expose minimal contracts, route/navigation entry points and stable domain types.','Keep implementation details and dependencies internal.','Define ownership and compatibility rules; avoid leaking UI implementation types.'],follow:'How do you handle cross-feature navigation without direct implementation dependency?',signals:'Thinks about contracts and team-scale evolution.',traps:'Sharing everything through a giant common module.',labs:['LAB 26']},
{id:'AR06',category:'Architecture & design',level:'Advanced',prompt:'How do you choose between a single source of truth in Room, network-first reads and cache-first reads?',answer:['Choose by freshness, offline requirements, write semantics and user expectations.','For offline-first, local storage can be the observable source while sync reconciles remote changes.','Define conflict policy, staleness metadata and error states explicitly.'],follow:'What if the server rejects a locally optimistic edit?',signals:'Understands consistency and product semantics.',traps:'Calling any cached response offline-first.',labs:['LAB 10','LAB 12']},
// Data and networking
{id:'D01',category:'Data & networking',level:'Core',prompt:'What is the difference between HTTP 401 and 403? How should a client react?',answer:['401 means authentication is missing/invalid; 403 means authenticated identity lacks permission (semantics may vary by API).','Refresh once only when contract allows; otherwise transition to signed-out state.','Do not retry authorization failures blindly.'],follow:'What if ten concurrent requests all receive 401?',signals:'Maps protocol semantics to bounded client behavior.',traps:'Refreshing on every 4xx or infinite retry.',labs:['LAB 11','LAB 18']},
{id:'D02',category:'Data & networking',level:'Intermediate',prompt:'How do you prevent concurrent token refresh requests from racing?',answer:['Use a single-flight/mutex strategy around refresh.','Re-check token inside lock because another request may already have refreshed it.','Persist new token pair atomically; replay eligible request once.','Handle refresh revocation and cancellation.'],follow:'Why must the failed request’s token be compared with the current token?',signals:'Can reason about race conditions and replay.',traps:'Locking without rechecking token; refreshing recursively.',labs:['LAB 11','LAB 18']},
{id:'D03',category:'Data & networking',level:'Intermediate',prompt:'Explain Room transactions, migrations and the role of indices.',answer:['Transactions group reads/writes atomically.','Migrations transform existing user data between schema versions and should be tested against real prior schemas.','Indices speed selected queries at write/storage cost; use EXPLAIN/query patterns to justify.'],follow:'How do you safely add a non-null column to a populated table?',signals:'Thinks about existing installed data, not just fresh installs.',traps:'Destructive migration in production without a deliberate policy.',labs:['LAB 10']},
{id:'D04',category:'Data & networking',level:'Intermediate',prompt:'How does Paging 3 handle loading, refresh, append and invalidation?',answer:['PagingSource loads pages; Pager emits PagingData; adapter/Compose consumes it.','Refresh and append have separate load states.','Stable ordering, keys and invalidation determine duplicate/gap behavior.'],follow:'How would you implement search with debounce and cancellation?',signals:'Understands paging state and UI integration.',traps:'Manual offset pagination with no stable sort.',labs:['LAB 36','LAB 02']},
{id:'D05',category:'Data & networking',level:'Advanced',prompt:'What is idempotency, and where must it be enforced for a payment or order request?',answer:['Same logical operation retried with same key should not create a second effect.','The authoritative server must enforce key uniqueness and response replay; client persistence keeps key stable across retry.','A new user intent gets a new key; key reuse with different payload should be rejected.'],follow:'What if server committed but the response was lost?',signals:'Understands distributed operation identity and unknown outcomes.',traps:'Thinking disabling a button is sufficient.',labs:['LAB 12','LAB 51']},
{id:'D06',category:'Data & networking',level:'Advanced',prompt:'How would you design an offline-first sync engine with conflict handling?',answer:['Local database is the UI source of truth; writes become durable pending operations.','Define pull/push ordering, cursor/versioning, conflict policy and idempotent server contract.','Retry with backoff and classify permanent vs transient errors.','Expose sync status and reconciliation to the user where needed.'],follow:'How do you avoid overwriting a newer local edit with an older server pull?',signals:'Can explain consistency model and recovery.',traps:'Blind last-write-wins without domain analysis.',labs:['LAB 12','LAB 15']},
{id:'D07',category:'Data & networking',level:'Advanced',prompt:'When would you choose WebSocket, SSE, polling or push notifications?',answer:['WebSocket for bidirectional low-latency session communication.','SSE for server-to-client streaming over HTTP where supported.','Polling is simpler when freshness needs are modest.','Push is a wake-up/delivery hint, not a durable source of truth.'],follow:'How do you recover missed events after reconnect?',signals:'Chooses protocol from interaction and lifecycle constraints.',traps:'Assuming push is guaranteed or WebSocket survives background.',labs:['LAB 28','LAB 47']},
// Testing, quality and performance
{id:'T01',category:'Testing & quality',level:'Core',prompt:'What should be unit tested vs integration tested vs UI tested in an Android app?',answer:['Unit tests verify pure business rules and state transitions quickly.','Integration tests verify boundaries such as database, serialization and repository behavior.','UI tests verify important user journeys and semantics; avoid duplicating every unit assertion.'],follow:'How would you test a ViewModel that combines two Flows?',signals:'Builds a test pyramid around risk and behavior.',traps:'Only screenshot tests or only unit tests.',labs:['LAB 24','LAB 25']},
{id:'T02',category:'Testing & quality',level:'Intermediate',prompt:'How do you test coroutines and Flow deterministically?',answer:['Use runTest and a shared TestCoroutineScheduler.','Inject dispatchers/time dependencies where appropriate.','Use Turbine or explicit collection to assert emissions, completion and errors.','Avoid Thread.sleep and real timing assumptions.'],follow:'What causes tests to hang when multiple test dispatchers use different schedulers?',signals:'Understands virtual time and scheduler coordination.',traps:'Mixing real Dispatchers.Main with test scheduler.',labs:['LAB 01','LAB 02','LAB 24']},
{id:'T03',category:'Testing & quality',level:'Intermediate',prompt:'How would you test Room migrations rather than only testing the latest schema?',answer:['Export schema history and construct database at old version.','Insert representative legacy rows, run migration and assert values/indices/constraints.','Test every supported upgrade path or a deliberate migration chain.'],follow:'How do you test a migration that changes a field from nullable to non-null?',signals:'Protects real user data across upgrades.',traps:'Only testing a fresh in-memory database.',labs:['LAB 10','LAB 24']},
{id:'T04',category:'Testing & quality',level:'Advanced',prompt:'How do you test retry, duplicate requests and unknown network outcomes?',answer:['Use controllable fake server to commit then drop response.','Assert same operation key is reused and no duplicate effect is created.','Test timeout, cancellation, 429, 5xx and permanent 4xx separately.','Verify user-visible state and durable local state.'],follow:'How would you make the test deterministic in CI?',signals:'Tests distributed failure semantics, not only happy path.',traps:'Mocking the API response without simulating server commit.',labs:['LAB 11','LAB 12','LAB 24']},
{id:'T05',category:'Performance & debugging',level:'Intermediate',prompt:'How do you investigate a memory leak in Android?',answer:['Reproduce lifecycle scenario and capture heap dump.','Inspect retained object path to GC root; distinguish expected cache from leak.','Use LeakCanary/Profiler and fix ownership/callback/listener lifecycle.','Verify leak disappears after repeated navigation.'],follow:'Why can a singleton holding an Activity cause a leak?',signals:'Uses evidence and reference paths.',traps:'Calling every retained object a leak.',labs:['LAB 22','LAB 45']},
{id:'T06',category:'Performance & debugging',level:'Advanced',prompt:'How would you optimize cold start without guessing?',answer:['Measure baseline with Macrobenchmark/startup metrics.','Inspect main-thread work, class loading, initialization, disk/network I/O.','Defer noncritical work and apply Baseline Profiles where appropriate.','Compare repeated runs on representative devices.'],follow:'What is the difference between Baseline Profile and Startup Profile?',signals:'Measurement-first and knows optimization mechanisms.',traps:'Removing dependencies without measuring effect.',labs:['LAB 21','LAB 20']},
{id:'T07',category:'Performance & debugging',level:'Advanced',prompt:'What is jank, and how do you trace a frame that misses its deadline?',answer:['Jank is a frame that misses expected presentation timing.','Inspect frame timeline/Perfetto, main and render thread, layout/measure/draw, GPU and allocations.','Fix the measured bottleneck and verify with frame metrics.'],follow:'How can image decode or synchronous database work affect scrolling?',signals:'Knows pipeline and profiling tools.',traps:'Assuming all jank is Compose recomposition.',labs:['LAB 20','LAB 23','LAB 46']},
{id:'T08',category:'Performance & debugging',level:'Advanced',prompt:'How would you debug a crash that only happens on one Android version or OEM?',answer:['Capture stack trace, device/API/build metadata and breadcrumbs.','Check platform behavior, permissions, vendor-specific APIs and feature flags.','Create minimal reproduction and test on emulator/physical devices.','Use staged rollout and crash monitoring to verify fix.'],follow:'How do you distinguish a regression from a pre-existing crash?',signals:'Production debugging and release discipline.',traps:'Assuming every OEM issue is unfixable.',labs:['LAB 35','LAB 45']},
// Security & background
{id:'S01',category:'Security & privacy',level:'Core',prompt:'What should never be stored in plain text or logged by an Android app?',answer:['Credentials, access/refresh tokens, payment secrets, private documents and unnecessary personal data.','Minimize data collected and persisted; classify and define retention.','Use platform-backed key management for appropriate secrets and keep authorization server-side.'],follow:'Does Android Keystore make a compromised app process safe?',signals:'Threat-models the device and process boundary.',traps:'Assuming encryption solves all client compromise.',labs:['LAB 17','LAB 18']},
{id:'S02',category:'Security & privacy',level:'Intermediate',prompt:'What is the Android Keystore, and what does it protect?',answer:['Stores cryptographic key material with hardware-backed protection where available.','App requests operations without exporting key material in many configurations.','Does not protect plaintext after decryption in a compromised process or replace server authorization.'],follow:'What happens when a key is invalidated after biometric enrollment changes?',signals:'Understands key lifecycle and limits.',traps:'Calling Keystore a secure database.',labs:['LAB 17']},
{id:'S03',category:'Security & privacy',level:'Advanced',prompt:'Would you implement certificate pinning? Explain benefits, operational risks and fallback strategy.',answer:['Pinning can reduce trust in unexpected CAs but adds certificate/key rotation and outage risk.','Use platform Network Security Config where appropriate; pin only with operational ownership and backup pins.','Never disable TLS validation as a workaround.'],follow:'How do you rotate pins without locking out old app versions?',signals:'Balances threat model and operational resilience.',traps:'Hardcoding one leaf certificate with no rotation plan.',labs:['LAB 17','LAB 11']},
{id:'S04',category:'Security & privacy',level:'Advanced',prompt:'How do you protect a deep link or exported component from unauthorized access?',answer:['Validate input and caller assumptions; exported status is an attack surface.','Authenticate and authorize resource access server-side for current user.','Use verified App Links for domain association, not as an authorization mechanism.'],follow:'Can a user forge an Intent to call an exported Activity?',signals:'Understands Android component security.',traps:'Trusting UI navigation path as access control.',labs:['LAB 27','LAB 43']},
{id:'S05',category:'Security & privacy',level:'Advanced',prompt:'How would you handle a compromised or rooted device in a high-risk app?',answer:['Define threat model and risk-based signals; root detection is bypassable.','Use server-side risk controls, step-up auth, transaction limits and anomaly monitoring.','Avoid storing long-lived secrets and never rely solely on client checks.'],follow:'What should happen if integrity verdict is unavailable?',signals:'Layered defense and graceful risk policy.',traps:'Treating root detection as guaranteed prevention.',labs:['LAB 17','LAB 18']},
// KMP
{id:'M01',category:'Kotlin Multiplatform',level:'Core',prompt:'What should be shared in KMP, and what should remain platform-specific?',answer:['Share stable business rules, models and portable data logic where reuse pays off.','Keep lifecycle, permissions, UI conventions and platform SDK integration native when sharing adds friction.','Choose boundaries based on team skill, product targets and dependency support.'],follow:'Would you share the entire ViewModel and navigation layer?',signals:'Pragmatic boundary reasoning.',traps:'Maximizing shared LOC as the goal.',labs:['LAB 38','LAB 41']},
{id:'M02',category:'Kotlin Multiplatform',level:'Intermediate',prompt:'Explain expect/actual and when an interface with dependency injection is a better option.',answer:['expect/actual provides compile-time platform-specific declarations/implementations across source sets.','Interfaces plus DI can improve testability and avoid platform coupling in shared code.','Use the least complex boundary that fits platform needs.'],follow:'How would you implement secure storage differently on Android and iOS?',signals:'Understands source sets and dependency inversion.',traps:'Using expect/actual for every platform difference.',labs:['LAB 38','LAB 40']},
{id:'M03',category:'Kotlin Multiplatform',level:'Advanced',prompt:'How do you expose Kotlin APIs to Swift, and what interop issues should you consider?',answer:['Understand generated Objective-C/Swift-facing API shape and nullability.','Manage suspend/Flow exposure, generics, naming and binary framework integration.','Consider lifecycle, memory ownership and toolchain compatibility; wrappers may improve ergonomics.'],follow:'What problem can SKIE solve, and what dependency does it introduce?',signals:'Can explain practical interop costs.',traps:'Assuming Kotlin APIs map directly to idiomatic Swift.',labs:['LAB 49']},
{id:'M04',category:'Kotlin Multiplatform',level:'Advanced',prompt:'How would you choose Room KMP vs SQLDelight for a shared database?',answer:['Compare supported targets, migration model, query generation, team familiarity and ecosystem maturity.','Check actual version/target compatibility and test on every target.','Do not choose only by syntax or a generic “best library” claim.'],follow:'How do you keep schema and migration behavior consistent across platforms?',signals:'Evaluates constraints and operational reality.',traps:'Assuming Android library support implies all KMP targets.',labs:['LAB 39']},
// AI
{id:'AI01',category:'AI & mobile ML',level:'Core',prompt:'How do you decide whether a mobile feature needs deterministic code, on-device ML or a hosted LLM?',answer:['Use deterministic code for explicit rules and exact outcomes.','Use on-device ML when privacy/offline/latency and task scope justify model footprint.','Use hosted LLM for flexible language tasks when network, cost, privacy and uncertainty are acceptable.','Define fallback and evaluation before choosing provider.'],follow:'Would you use an LLM to calculate a bank balance or validate a tax total?',signals:'Chooses technology from product constraints.',traps:'Using generative output for deterministic business rules.',labs:['LAB 51','LAB 52']},
{id:'AI02',category:'AI & mobile ML',level:'Intermediate',prompt:'Why must an LLM provider API key not be embedded in an Android APK?',answer:['APK contents can be inspected and secrets extracted.','Use a trusted backend to hold provider credentials, enforce quotas and authorization.','App attestation and obfuscation do not turn a distributed client secret into a secret.'],follow:'What if the app calls a provider directly using Firebase AI Logic?',signals:'Understands client credential exposure and managed security controls.',traps:'Saying ProGuard hides the key.',labs:['LAB 51']},
{id:'AI03',category:'AI & mobile ML',level:'Intermediate',prompt:'How do you build a streaming LLM UI that supports cancellation and process recreation?',answer:['Model generation as a state machine with request/generation ID.','Propagate cancellation through Flow/HTTP/backend when supported.','Persist user message and partial status; define whether generation continues server-side.','Ignore stale chunks and distinguish partial from completed output.'],follow:'What if a late chunk arrives after the user starts another prompt?',signals:'Treats AI as asynchronous distributed work.',traps:'Appending chunks to whichever screen is visible.',labs:['LAB 53']},
{id:'AI04',category:'AI & mobile ML',level:'Advanced',prompt:'What is RAG, and how do you prevent it from leaking documents or citing stale content?',answer:['Ingest, chunk, embed, retrieve and pass relevant context to generation.','Filter retrieval by authorization at query time, not only during indexing.','Version chunks and invalidate on document change/deletion.','Citations must map to actual source passages; abstain when evidence is weak.'],follow:'Why is RAG not a guarantee against hallucinations?',signals:'Understands retrieval and authorization separately from generation.',traps:'Treating vector similarity as permission or truth.',labs:['LAB 55']},
{id:'AI05',category:'AI & mobile ML',level:'Advanced',prompt:'How do you evaluate a generative feature when exact output string matching is unsuitable?',answer:['Use a representative golden set with task-specific rubrics.','Measure schema validity, factual grounding, task completion, refusal/abstention and user correction.','Pin model/prompt versions and combine automated checks with sampled human review.','Track latency, errors and cost separately from quality.'],follow:'What would be a release-blocking regression for a document assistant?',signals:'Treats quality as an engineering metric.',traps:'Judging one demo or relying only on model self-evaluation.',labs:['LAB 57']},
{id:'AI06',category:'AI & mobile ML',level:'Advanced',prompt:'What is prompt injection, and why is “the model should ignore malicious instructions” not a sufficient defense?',answer:['Untrusted content can contain instructions that influence model behavior.','Separate instructions and data, but assume model-level separation can fail.','Enforce authorization and tool allowlists in deterministic code; require confirmation for side effects.','Treat retrieved documents and tool output as untrusted.'],follow:'Can a retrieved PDF authorize a tool to export another user’s file?',signals:'Security boundary outside model prompt.',traps:'Relying on prompt wording as access control.',labs:['LAB 54','LAB 55','LAB 57']},
{id:'AI07',category:'AI & mobile ML',level:'Advanced',prompt:'When would you run a model on-device instead of through a backend?',answer:['On-device offers offline capability and can reduce data transfer/privacy exposure.','Costs include APK/model delivery size, RAM, thermal/battery, device fragmentation and model updates.','Benchmark representative devices and provide fallback for unsupported hardware.'],follow:'How do you choose between ML Kit and LiteRT for a feature?',signals:'Understands deployment/runtime constraints.',traps:'Assuming on-device is always cheaper or faster.',labs:['LAB 52','LAB 56']},
// System design / product engineering
{id:'SD01',category:'System design & product cases',level:'Intermediate',prompt:'Design an offline-first notes app. Explain local schema, sync queue, conflict policy and recovery.',answer:['Room as local source of truth for UI.','Persist pending operations with stable IDs and sync status.','Use version/cursor and explicit conflict policy.','Retry transient failures with backoff; surface permanent conflicts.'],follow:'What if the same note is edited on two devices while offline?',signals:'End-to-end state and consistency reasoning.',traps:'“Just sync when internet returns”.',labs:['LAB 10','LAB 12','LAB 15']},
{id:'SD02',category:'System design & product cases',level:'Intermediate',prompt:'Design a paginated product feed that supports search, filters and refresh.',answer:['Stable sort and cursor/page contract.','Debounce query and cancel obsolete searches.','Separate refresh/append load states and handle duplicate/gap prevention.','Cache strategy and empty/error states are explicit.'],follow:'What happens when a product is inserted at the top between page requests?',signals:'Understands data ordering and UI state.',traps:'Offset pagination without stable ordering.',labs:['LAB 36','LAB 02']},
{id:'SD03',category:'System design & product cases',level:'Advanced',prompt:'Design a POS app that must sell while offline and sync when multiple terminals reconnect.',answer:['Durable local order/outbox and globally unique operation IDs.','Server owns stock and authoritative order acceptance.','Define oversell policy and conflict resolution; never silently rewrite a completed sale.','Printer/payment side effects have independent states and recovery.'],follow:'How would you handle two devices selling the last item?',signals:'Understands distributed constraints and business trade-offs.',traps:'Assuming client stock is authoritative.',labs:['LAB 12','LAB 15','POS-C1']},
{id:'SD04',category:'System design & product cases',level:'Advanced',prompt:'Design a wallet transfer flow that remains correct when the response is lost after server commit.',answer:['Create stable operation/idempotency key per user intent.','Server enforces uniqueness and exposes operation status.','Client persists pending reference and treats timeout as unknown.','Reconcile from canonical server state; do not create a new transfer on retry.'],follow:'How do you communicate unknown outcome without alarming the user?',signals:'Financial correctness and failure semantics.',traps:'Showing failed on timeout.',labs:['LAB 12','FT-C2','FT-C3']},
{id:'SD05',category:'System design & product cases',level:'Advanced',prompt:'Design a real-time chat client that works across network changes and process death.',answer:['Persist messages locally with state and server IDs.','Use socket for live delivery but fetch missed events after reconnect.','Deduplicate/order by server sequence; push is a wake-up hint.','Resumable attachment uploads and lifecycle-aware work.'],follow:'What if delivery receipt arrives before the message acknowledgement?',signals:'Event ordering and source-of-truth reasoning.',traps:'Treating socket send as delivered.',labs:['LAB 12','LAB 47','MSG-02']},
{id:'SD06',category:'System design & product cases',level:'Advanced',prompt:'Design secure document upload/download for a mobile app.',answer:['Use scoped file access and temporary files.','Resumable upload/download with checksums and durable task state.','Short-lived authorization and server ownership checks.','Clean up partial data and protect sensitive local content.'],follow:'How do you avoid exposing partial downloads as completed files?',signals:'Storage, security and background work integrated.',traps:'Keeping permanent broad storage permissions.',labs:['LAB 15','LAB 17','LAB 31']},
{id:'SD07',category:'System design & product cases',level:'Advanced',prompt:'Design a media player that supports background playback, interruptions and offline downloads.',answer:['Separate player/session lifecycle from screen lifecycle.','Handle audio focus, media session, foreground service policy and notification controls.','Persist playback position and download state.','Bound cache and recover from partial download.'],follow:'What should happen on headset unplug or audio focus loss?',signals:'Platform policy and resource ownership.',traps:'Keeping Activity alive to own playback.',labs:['LAB 16','LAB 15']},
{id:'SD08',category:'System design & product cases',level:'Advanced',prompt:'Design a location-tracking delivery app with battery and permission constraints.',answer:['Request only contextual permissions; support approximate/denied states.','Choose location accuracy and cadence by product need.','Use permitted foreground service for user-visible tracking when justified.','Upload with durable batching and show stale timestamps.'],follow:'What if user revokes background location during an active trip?',signals:'Permission, battery and background constraints.',traps:'Polling GPS continuously.',labs:['LAB 14','LAB 15','LAB 29']},
{id:'SD09',category:'System design & product cases',level:'Advanced',prompt:'Design a multi-module app for several feature teams with independent releases and build performance goals.',answer:['Define module graph around features and stable API contracts.','Enforce dependency direction and convention plugins.','Measure configuration/build/compile time before and after.','Define ownership, test boundaries and migration strategy.'],follow:'How do you prevent feature modules depending on each other’s implementations?',signals:'Scalability without overengineering.',traps:'Micro-modules without cohesion.',labs:['LAB 26','LAB 33']},
{id:'SD10',category:'System design & product cases',level:'Advanced',prompt:'Design an AI assistant that answers from private user documents and can create actions.',answer:['Ingestion pipeline with versioned chunks and document ownership.','Retrieval authorization at query time and citations to source offsets.','Structured action proposals validated by domain/server and confirmed by user.','Streaming cancellation, evaluation, rate limits, privacy and rollback.'],follow:'How do you prevent a malicious document from causing a tool action?',signals:'Treats model output as untrusted and builds explicit guardrails.',traps:'Prompt-only security.',labs:['LAB 54','LAB 55','LAB 57']},
{id:'SD11',category:'System design & product cases',level:'Advanced',prompt:'How would you architect an app that must support phone, tablet, foldable and desktop layouts?',answer:['Adaptive layouts based on window size/posture rather than device labels.','Preserve navigation and state across resizing/folding.','Separate responsive UI decisions from domain logic.','Test window classes, hinge occlusion, multi-window and accessibility.'],follow:'What if a fold occurs while a detail pane is open?',signals:'Adaptive product behavior and state continuity.',traps:'Orientation-only layouts.',labs:['LAB 50','LAB 46']},
{id:'SD12',category:'System design & product cases',level:'Advanced',prompt:'Design a robust authentication/session architecture for a mobile app.',answer:['Define access/refresh token lifecycle and server revocation behavior.','Store credentials with appropriate platform-backed protection.','Coordinate refresh single-flight and handle concurrent 401s.','Logout clears local sensitive state; server remains authorization authority.'],follow:'What happens if refresh succeeds but persisting the new token fails?',signals:'Security and concurrency reasoning.',traps:'Infinite refresh/retry loops.',labs:['LAB 17','LAB 18','LAB 11']}
];

// Additional practical coverage often missed by Compose-only preparation: legacy Android, JVM/build tooling, coding and ownership rounds.
INTERVIEW_QUESTION_BANK.push(
{id:'P01',category:'Android components & legacy platform',level:'Core',prompt:'What is the difference between Activity, Service, BroadcastReceiver and ContentProvider?',answer:['Activity owns a user-facing interaction surface and participates in task/lifecycle behavior.','Service represents work/interaction without a UI; foreground service has user-visible notification and strict platform policy.','BroadcastReceiver handles a broadcast event briefly; long work should be handed off to an appropriate scheduler.','ContentProvider exposes structured data through a permissioned URI contract and ContentResolver.'],follow:'Why should onReceive() not perform a long network request?',signals:'Knows platform component contracts and lifecycle constraints.',traps:'Treating Service as a background thread or receiver as a long-running worker.',labs:['LAB 14','LAB 15','LAB 16','LAB 43']},
{id:'P02',category:'Android components & legacy platform',level:'Core',prompt:'Explain Fragment lifecycle and how it differs from the Fragment view lifecycle.',answer:['Fragment instance can outlive its view; view lifecycle has its own owner.','Bind view observers to viewLifecycleOwner and clear view binding in onDestroyView.','Avoid retaining Activity/View references beyond their lifecycle.'],follow:'Why can observing LiveData with the Fragment as owner leak or update a destroyed view?',signals:'Understands old and current Android UI codebases.',traps:'Assuming Fragment onDestroyView means Fragment instance is destroyed.',labs:['LAB 03','LAB 05']},
{id:'P03',category:'Android components & legacy platform',level:'Intermediate',prompt:'How does RecyclerView recycling work, and how do stable IDs and DiffUtil help?',answer:['ViewHolder instances are reused to avoid inflating/binding every row.','DiffUtil calculates changes between old/new lists; stable identity helps preserve item continuity.','Binding must reset all recycled visual state and avoid capturing stale positions.'],follow:'Why should you not retain the bind-time adapter position in a click listener?',signals:'Can reason about classic Views as well as Compose.',traps:'Mutating the same list instance and expecting DiffUtil to detect old contents.',labs:['LAB 20','LAB 25']},
{id:'P04',category:'Android components & legacy platform',level:'Intermediate',prompt:'What is the difference between startService, bindService and a foreground service?',answer:['Started service has an independent started lifetime until stopped; bound service serves clients while bound.','Foreground service is for ongoing user-noticeable work and must meet current service type/permission/policy requirements.','Modern Android background execution restrictions mean neither is a universal scheduler.'],follow:'Would you use a Service for a one-off log upload?',signals:'Uses lifecycle and current OS policy in design.',traps:'Treating every background task as foreground service.',labs:['LAB 15','LAB 16']},
{id:'P05',category:'Android components & legacy platform',level:'Advanced',prompt:'How would you design a ContentProvider query API and avoid loading a huge Cursor into memory?',answer:['Define stable URI paths, MIME types, projection, selection, sort order and permissions.','Use Cursor-based paging/selection and close cursors reliably.','Avoid large Binder payloads; support cancellation and query limits where appropriate.'],follow:'What is CursorWindow and what can cause CursorWindow allocation/size failures?',signals:'Understands provider contract, Cursor lifecycle and IPC boundaries.',traps:'Returning giant arrays or keeping cursor open indefinitely.',labs:['LAB 10','LAB 43']},
{id:'P06',category:'Android components & legacy platform',level:'Advanced',prompt:'What happens during app startup before the first Activity is visible, and how can ContentProviders affect startup?',answer:['Process creation, Application initialization, provider initialization and Activity launch all contribute.','Library providers may initialize before Application onCreate depending on manifest/AndroidX startup configuration.','Measure startup and defer noncritical initialization; do not guess.'],follow:'How do you find which initializer regressed cold start?',signals:'Understands real Android startup path.',traps:'Assuming only Application.onCreate controls startup.',labs:['LAB 21','LAB 45']},
{id:'P07',category:'Android components & legacy platform',level:'Advanced',prompt:'How do you handle configuration changes, multi-window resizing and fold/unfold without losing UI state?',answer:['Treat window size/posture as dynamic input, not fixed device category.','Keep domain state outside disposable UI views and preserve navigation identity.','Use adaptive layouts and test live resize/fold transitions.'],follow:'What should happen to a selected detail item when a two-pane layout becomes single-pane?',signals:'Adaptive UI and state ownership.',traps:'Recreating data loads on every size change.',labs:['LAB 05','LAB 50']},
{id:'J01',category:'JVM, Java & build tooling',level:'Core',prompt:'What is the difference between val and immutability in Kotlin?',answer:['val prevents reassignment of the reference, not mutation of the referenced object.','Use immutable data structures/snapshots and avoid exposing mutable collections.','Thread safety requires ownership or synchronization, not val alone.'],follow:'Can a val MutableList be modified?',signals:'Distinguishes reference immutability from object immutability.',traps:'Saying val means the object cannot change.',labs:['LAB 37','LAB 02']},
{id:'J02',category:'JVM, Java & build tooling',level:'Intermediate',prompt:'Explain JVM heap, stack, garbage collection and why Android memory leaks still happen.',answer:['Objects generally live on managed heap; stack frames hold local references/primitive values and call state.','GC reclaims unreachable objects, not objects still reachable through accidental references.','Android leaks commonly arise from longer-lived owners retaining Activity/View/context/callbacks.'],follow:'Why can a static/singleton reference to an Activity leak it?',signals:'Basic runtime model and lifecycle-aware ownership.',traps:'Thinking GC automatically cleans up any Activity after onDestroy.',labs:['LAB 22']},
{id:'J03',category:'JVM, Java & build tooling',level:'Intermediate',prompt:'What are equals and hashCode contracts, and why do they matter for HashMap/HashSet?',answer:['Equal objects must have equal hash codes.','Hash code chooses bucket; equals resolves collisions.','Mutating fields used in hashCode while an object is a map key can make lookup fail.'],follow:'Why are data classes with mutable properties risky as map keys?',signals:'Core language/runtime understanding.',traps:'Assuming hashCode uniquely identifies an object.',labs:['LAB 37']},
{id:'J04',category:'JVM, Java & build tooling',level:'Advanced',prompt:'What happens during Gradle configuration and execution, and how do you investigate slow builds?',answer:['Gradle configures project/task graph then executes selected tasks; configuration cache/build cache affect different work.','Use Build Scans/profiling and task timings to identify configuration, dependency, compilation or packaging bottlenecks.','Avoid eager task realization and unnecessary cross-module coupling.'],follow:'What is the difference between build cache and configuration cache?',signals:'Can diagnose build performance systematically.',traps:'Adding more Gradle workers without measuring bottleneck.',labs:['LAB 26','LAB 33']},
{id:'J05',category:'JVM, Java & build tooling',level:'Advanced',prompt:'How do R8, shrinking, obfuscation and keep rules affect a production Android build?',answer:['R8 performs shrinking, optimization and obfuscation based on reachability/configuration.','Reflection, JNI, serialization and dynamic access may need precise keep rules.','Test minified release builds; debug success does not prove release correctness.'],follow:'Why can a serialization model work in debug and fail in minified release?',signals:'Understands shipping and runtime compatibility.',traps:'Adding broad keep-all rules without understanding impact.',labs:['LAB 33','LAB 35']},
{id:'CP01',category:'Coding & problem solving',level:'Core',prompt:'Given a list of transactions, return the first duplicate transaction ID. Explain time and space complexity.',answer:['Use a HashSet while scanning once.','Expected O(n) time and O(n) additional space.','Clarify whether null/blank IDs are valid and whether equality is case-sensitive.'],follow:'How would the solution change if memory is constrained and the input is sorted?',signals:'Clarifies constraints, chooses data structure and states complexity.',traps:'Nested loops without discussing scale.',labs:['LAB 37']},
{id:'CP02',category:'Coding & problem solving',level:'Core',prompt:'How would you implement an LRU cache and what should its get/put complexity be?',answer:['HashMap maps keys to nodes; doubly linked list maintains recency.','get and put are O(1) average; evict tail when capacity exceeded.','Define capacity zero, update existing key and null/value semantics.'],follow:'How would you make it thread-safe?',signals:'Can implement a known data structure and reason about invariants.',traps:'Using LinkedHashMap without understanding access-order behavior when asked to implement.',labs:['LAB 37']},
{id:'CP03',category:'Coding & problem solving',level:'Intermediate',prompt:'Given a stream of search queries, implement debounce and latest-request-wins behavior.',answer:['Debounce groups rapid input events and emits after quiet period.','flatMapLatest/cancellation stops obsolete work, but underlying API may not cooperate.','Use request generation/version check to ignore late responses.'],follow:'What if cancellation cannot stop the network request?',signals:'Combines algorithmic thinking with mobile async behavior.',traps:'Debounce alone guarantees stale response cannot arrive.',labs:['LAB 02','LAB 11']},
{id:'CP04',category:'Coding & problem solving',level:'Intermediate',prompt:'How would you merge two sorted transaction lists while preserving stable order?',answer:['Use two pointers and compare timestamps/sequence.','O(n+m) time and O(n+m) output (or O(1) auxiliary if in-place constraints allow).','Define tie-breaker and null/duplicate policy.'],follow:'What if timestamps are equal but server sequence differs?',signals:'Communicates invariants and complexity.',traps:'Sorting concatenated lists without considering required stable ordering.',labs:['LAB 36']},
{id:'CP05',category:'Coding & problem solving',level:'Advanced',prompt:'Implement a bounded retry policy with exponential backoff and jitter. What should never be retried?',answer:['Classify transient transport/5xx/429 separately from permanent validation/auth/business errors.','Use exponential growth with cap and jitter to avoid synchronized retry storms.','Respect Retry-After and operation idempotency; cancellation stops retries.'],follow:'Why is retrying a payment POST dangerous without idempotency?',signals:'Connects algorithm, distributed systems and product correctness.',traps:'Retry all exceptions forever.',labs:['LAB 11','LAB 12','LAB 15']},
{id:'B01',category:'Behavioral & ownership',level:'Intermediate',prompt:'Tell me about a production bug you owned. How did you investigate, communicate, fix and verify it?',answer:['Set context and user impact; distinguish facts from assumptions.','Explain reproduction, evidence, root cause and options considered.','Describe mitigation, durable fix, rollout and post-fix monitoring.','State what you changed to prevent recurrence.'],follow:'What would you do differently if the same incident happened again?',signals:'Ownership, structured communication and learning.',traps:'Blaming another team or describing only the code change.',labs:['LAB 35','LAB 45']},
{id:'B02',category:'Behavioral & ownership',level:'Advanced',prompt:'Describe a technical decision you disagreed with. How did you influence the outcome?',answer:['Explain constraints and competing goals fairly.','Use evidence, prototypes or measurements rather than preference.','Describe how you aligned and supported the final decision.','Reflect on what you learned.'],follow:'What if the team chose the option you argued against?',signals:'Collaboration without ego and ability to disagree constructively.',traps:'Portraying colleagues as incompetent.',labs:['LAB 26','LAB 50']},
{id:'B03',category:'Behavioral & ownership',level:'Advanced',prompt:'How do you decide when to refactor versus ship a feature under deadline pressure?',answer:['Estimate user risk, change frequency, coupling and cost of delay.','Choose smallest safe refactor around the feature; make debt visible with owner and trigger.','Use tests/observability to protect existing behavior.'],follow:'What signals would make you stop and refactor before adding the feature?',signals:'Pragmatic judgment and risk management.',traps:'Always rewrite or never touch legacy code.',labs:['LAB 26','LAB 24']},
{id:'B04',category:'Behavioral & ownership',level:'Advanced',prompt:'How would you mentor a junior engineer whose implementation works but has fragile lifecycle and error handling?',answer:['Review observable behavior and explain the failure scenario.','Pair on ownership/state model and add a focused test.','Give actionable feedback and let them own the fix.','Follow up on understanding, not only patch acceptance.'],follow:'How do you avoid taking over the implementation?',signals:'Mentorship and raising team quality.',traps:'Rewriting their code without teaching the reasoning.',labs:['LAB 03','LAB 24']}
);

